(SELECT DISTINCT i.i_item_id, CASE WHEN (SELECT SUM(ss2.ss_quantity) FROM store_sales ss2 WHERE ss2.ss_item_sk = ss.ss_item_sk) > 1000 THEN 'High' ELSE 'Low' END AS sales_volume_flag, CASE WHEN ss.ss_net_profit > 0 THEN 'Profit' ELSE 'Loss' END AS profit_category FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk WHERE i.i_current_price > 50 AND s.s_state = 'CA') INTERSECT (SELECT DISTINCT i.i_item_id, CASE WHEN (SELECT SUM(cs2.cs_quantity) FROM catalog_sales cs2 WHERE cs2.cs_item_sk = cs.cs_item_sk) > 500 THEN 'High' ELSE 'Low' END AS sales_volume_flag, CASE WHEN cs.cs_net_profit > 0 THEN 'Profit' ELSE 'Loss' END AS profit_category FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE i.i_current_price > 75 AND cp.cp_department = 'Electronics' AND sm.sm_carrier = 'UPS') LIMIT 100
